// A JARVIS workflow failed (n8n Error Trigger). Build a short Telegram alert; skip repeats of the
// same problem within 60 minutes so one broken step cannot flood the owner's phone.
const j = $input.first().json || {};
const ex = j.execution || {}, wf = j.workflow || {}, er = ex.error || {};
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const wfName = wf.name || 'a workflow';
const step = ex.lastNodeExecuted || (er.node && er.node.name) || 'unknown step';
const msg = String(er.message || er.description || 'no error message').replace(/\s+/g, ' ').slice(0, 300);
const store = $getWorkflowStaticData('global');
store.recent = store.recent || {};
const key = wfName + '|' + step + '|' + msg.slice(0, 80);
const now = Date.now();
for (const k of Object.keys(store.recent)) if (now - store.recent[k] > 3600e3) delete store.recent[k];
const repeat = !!store.recent[key];
store.recent[key] = now;
const local = new Date().toLocaleString('en-CA', { timeZone: 'America/Toronto', dateStyle: 'medium', timeStyle: 'short' });
const text = [
  '⚠️ <b>JARVIS: something failed</b>',
  'Workflow: <b>' + esc(wfName) + '</b>',
  'Step: ' + esc(step),
  'Problem: ' + esc(msg),
  'When: ' + esc(local) + (ex.mode ? ' (' + esc(ex.mode) + ' run)' : ''),
  ex.url ? 'Details: ' + esc(ex.url) : '',
  'Nothing else was changed. Send me (Claude) a photo of this message and I will fix it.',
].filter(Boolean).join('\n');
return [{ json: { send: !repeat, text, kind: 'error', summary: `Error in workflow "${wfName}" at step "${step}" (${local}): ${msg}` } }];

// Only the two memory columns (the data table has kind + summary).
const j = $input.first().json;
return [{ json: { kind: j.kind, summary: String(j.summary).slice(0, 1500) } }];

// Daily health check (and Monday 10:40 check that the weekly research report went out).
// Silent when everything is fine; one Telegram alert listing the problems otherwise.
const problems = [];
const ai = $('Check AI (free combo)').first().json || {};
// A reply with at least one choice counts as working (reasoning models can return empty text for tiny limits).
const aiOk = !ai.error && Array.isArray(ai.choices) && ai.choices.length > 0;
if (!aiOk) problems.push('Free AI (OmniRoute) did not answer' + (ai.error ? ': ' + String(ai.error.message || ai.error).slice(0, 150) : ''));
const tts = $('Check voice service').first().json || {};
if (tts.error || tts.status !== 'ok') problems.push('Voice service (Kokoro/Piper) did not answer');
const rows = $('Read memory').all().map(i => i.json || {});
const tz = 'America/Toronto';
const nowT = new Date();
const dow = nowT.toLocaleDateString('en-CA', { timeZone: tz, weekday: 'short' });
const hour = Number(nowT.toLocaleString('en-CA', { timeZone: tz, hour: '2-digit', hour12: false })) % 24;
if (dow === 'Mon' && hour >= 10) {
  const day = d => new Date(d).toLocaleDateString('en-CA', { timeZone: tz });
  const sentRecently = rows.some(r => r.kind === 'research' && r.createdAt && day(r.createdAt) === day(nowT));
  if (!sentRecently) problems.push('The Monday 10:00 product research report was not sent (is "JARVIS Research v1" published?)');
}
const local = nowT.toLocaleString('en-CA', { timeZone: tz, dateStyle: 'medium', timeStyle: 'short' });
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const text = '⚠️ <b>JARVIS health check</b> (' + esc(local) + ')\n' + problems.map(p => '• ' + esc(p)).join('\n') +
  '\nSend me (Claude) a photo of this message and I will fix it.';
return [{ json: { send: problems.length > 0, text, kind: 'error', summary: 'Health check problems (' + local + '): ' + problems.join('; ') } }];

// Only the two memory columns (the data table has kind + summary).
const j = $input.first().json;
return [{ json: { kind: j.kind, summary: String(j.summary).slice(0, 1500) } }];
